		{
			Bucket bucket;

			if (Mark::markTlsIndex != 0)
			{
				const int firstBucket = currentBucket + 2047;
				const size_t count = std::min((size_t)std::max((int)(window / bucketTimeSpan), 1), (size_t)2046);
				for (size_t i = 0; i < count; ++i)
